/// User-facing status strings generated by the engine itself. Provider and
/// backend supplied status text is always passed through untouched.
final class AiStreamMessages {
  /// Status shown while a tool call is being assembled.
  final String Function(String toolName) callingTool;

  const AiStreamMessages({this.callingTool = _englishCallingTool});

  /// English strings (default).
  static const AiStreamMessages english = AiStreamMessages();

  /// Arabic strings.
  static const AiStreamMessages arabic =
      AiStreamMessages(callingTool: _arabicCallingTool);
}

String _englishCallingTool(String toolName) => 'Calling tool ($toolName)...';
String _arabicCallingTool(String toolName) =>
    'جارٍ استدعاء الأداة ($toolName)...';
